/* Cast image fixes: keep actor faces visible without affecting the hero image. */
.actor-trio img, .actor-card img, .cast-card img, .actor-grid img, .cullen-card img, .supporting-card img, .wolf-card img, .volturi-card img {
    width:100%;
    height:260px;
    object-fit:cover;
    object-position:center top;
}
@media(max-width:700px){
    .actor-trio img, .actor-card img, .cast-card img, .actor-grid img, .cullen-card img, .supporting-card img, .wolf-card img, .volturi-card img { height:240px; }
}
.img-placeholder { min-height:220px; display:flex; align-items:center; justify-content:center; text-align:center; padding:20px; background:#d8d0bf; color:#1e3a5f; font-family:'Playfair Display',serif; font-size:0.95rem; }
